// === Tab: mySketch ===
// reference: https://p5js.org/reference/#/p5/createShader

let mandel;
let x0 = -0.74364388703,
	y0 = 0.13182590421,
	delta = 0.000002;

function setup() {
	pixelDensity(1);
	createCanvas(800, 800, WEBGL);

	// create and initialize the shader
	mandel = createShader(vs, fs);
	shader(mandel);
	noStroke();

	// 'p' is the center point of the Mandelbrot image
	mandel.setUniform('p', [x0, y0]);
	mandel.setUniform('resolution', [width, height]);
	describe('zooming Mandelbrot set. a colorful, infinitely detailed fractal.');
}

function draw() {
	// 'r' is the size of the image in Mandelbrot-space
	let r = 2.0 * exp(-6.0 * (1 + sin(millis() / 1000)))

	if (keyIsDown(LEFT_ARROW)) {
		x0 -= delta;
	} else if (keyIsDown(RIGHT_ARROW)) {
		x0 += delta;
	} else if (keyIsDown(UP_ARROW)) {
		y0 += delta;
	} else if (keyIsDown(DOWN_ARROW)) {
		y0 -= delta;
	}


	mandel.setUniform('p', [x0, y0]);
	mandel.setUniform('r', r);
	plane(width, height);
}

// === Tab: vert ===
// the vertex shader is called for each vertex
let vs = `
precision highp float;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
	// gl_Position = positionVec4;
 }
`;


// === Tab: frag ===
// the fragment shader is called for each pixel
let fs = `
   precision highp float;
   uniform vec2 p;
	 uniform vec2 resolution;
   uniform float r;
   const int I = 500;

   void main() {
     vec2 c = p + (gl_FragCoord.xy/resolution.xy - 0.5) * r, z = c;
     float n = 0.0;
     for (int i = I; i > 0; i --) {
       if(z.x*z.x+z.y*z.y > 4.0) {
         n = float(i)/float(I);
         break;
       }
       z = vec2(z.x*z.x-z.y*z.y, 2.0*z.x*z.y) + c;
     }
     // gl_FragColor = vec4(0.5-cos(n*17.0)/2.0,0.5-cos(n*13.0)/2.0,0.5-cos(n*23.0)/2.0,1.0);
		 gl_FragColor = vec4(0.5 - 0.5*cos(n*vec3(17., 13., 23.)), 1.0);
   }`;

